"""Contact sheet rows for substitute teachers."""

from typing import Iterable, List
from rosterkit.models import Student
from rosterkit.errors import ProjectError


def _sort_key(student: Student) -> str:
    return student.display_name.casefold()


def _check(students: List[Student]) -> None:
    if not students:
        raise ProjectError("no students for contact sheet")
    for student in students:
        if not student.email:
            raise ProjectError(
                f"no email for {student.display_name}"
            )


def _cells(student: Student) -> List[str]:
    return [
        student.display_name,
        student.section,
        student.email
    ]


def _widths(table: List[List[str]]) -> List[int]:
    return [
        max(len(line[index]) for line in table)
        for index in range(3)
    ]


def _line(cells: List[str], sizes: List[int]) -> str:
    padded = [
        text.ljust(size)
        for text, size in zip(cells, sizes)
    ]
    return "  ".join(padded).rstrip()


# ---
def format_contacts(
    students: Iterable[Student]
) -> List[str]:
    """One row per student: name, section and email."""
    roster = sorted(students, key=_sort_key)
    _check(roster)
    table = [_cells(item) for item in roster]
    sizes = _widths(table)
    return [_line(item, sizes) for item in table]

