import unittest

from tests.support import data_file
from rosterkit.reader import read_roster
from rosterkit.models import Student
from rosterkit.errors import ProjectError
from rosterkit.contacts import format_contacts


def make_student(last, first, section="A", email="x@y.z"):
    return Student("1", last, first, section, email)


class FormatContactsTests(unittest.TestCase):
    def test_sorted_and_aligned(self):
        rows = format_contacts(
            [
                make_student("Zed", "Al", "B", "al@s.org"),
                make_student("Longname", "Bo", "A", "bo@s.org")
            ]
        )
        self.assertEqual(
            rows,
            [
                "Longname, Bo  A  bo@s.org",
                "Zed, Al       B  al@s.org"
            ]
        )

    def test_missing_email_names_student(self):
        students = [make_student("Smith", "Jo", email=None)]
        with self.assertRaises(ProjectError) as caught:
            format_contacts(students)
        self.assertIn("Smith, Jo", str(caught.exception))

    def test_empty_list_raises(self):
        with self.assertRaises(ProjectError):
            format_contacts([])

    def test_sample_roster_rows_match_in_columns(self):
        students = read_roster(data_file("roster.csv"))
        with_mail = [
            item for item in students if item.email
        ]
        rows = format_contacts(with_mail)
        self.assertEqual(len(rows), len(with_mail))
